#!/usr/bin/env python3
"""
Check which years from 2000-2010 have CO Daily AQI Values in the Good (<=4.4 ppm) range
for every day in the entire year across all monitor sites for each area.
"""

import json
import subprocess
import sys

CBSAS = {
    "Portland-Vancouver-Hillsboro, OR-WA": "38900",
    "Wichita, KS": "48620",
    "San Diego-Carlsbad, CA": "41740"
}

CO_PARAM = "42101"
GOOD_THRESHOLD = 4.4  # ppm

def analyze_json_file(filename):
    """Analyze a downloaded JSON file"""
    try:
        with open(filename) as f:
            data = json.load(f)
    except:
        return False, 0, 0, []

    if 'Data' not in data or not data['Data']:
        return False, 0, 0, []

    date_sites = {}
    max_val = 0

    for r in data['Data']:
        val = r.get('first_max_value', r.get('arithmetic_mean', 0))
        date = r.get('date_local')
        site = f"{r.get('state_code')}-{r.get('county_code')}-{r.get('site_number')}"

        if val is None:
            continue

        key = (date, site)
        if key not in date_sites or val > date_sites[key]:
            date_sites[key] = val

        if val > max_val:
            max_val = val

    bad_dates = set()
    for (date, site), val in date_sites.items():
        if val > GOOD_THRESHOLD:
            bad_dates.add(date)

    is_good = len(bad_dates) == 0
    return is_good, max_val, len(date_sites), sorted(bad_dates)

def download_data(cbsa_code, year):
    """Download data for a CBSA and year"""
    bdate = f"{year}0101"
    edate = f"{year}1231"
    filename = f"{cbsa_code}_{year}.json"

    url = f"https://aqs.epa.gov/data/api/dailyData/byCBSA?email=test@aqs.api&key=test&param={CO_PARAM}&bdate={bdate}&edate={edate}&cbsa={cbsa_code}"

    try:
        result = subprocess.run(
            ["curl", "-s", "-o", filename, url],
            capture_output=True,
            text=True,
            timeout=30
        )
        if result.returncode != 0:
            print(f"  Error downloading {filename}: {result.stderr}", file=sys.stderr)
            return None
        return filename
    except Exception as e:
        print(f"  Error downloading {filename}: {e}", file=sys.stderr)
        return None

def main():
    results = {cbsa_name: {} for cbsa_name in CBSAS}

    for year in range(2000, 2011):
        print(f"\nYear {year}:")
        for cbsa_name, cbsa_code in CBSAS.items():
            print(f"  Downloading {cbsa_name}...", end=" ", flush=True)
            filename = download_data(cbsa_code, year)
            if filename is None:
                print("FAILED")
                results[cbsa_name][year] = {
                    "is_good": False,
                    "max_value": 0,
                    "days_checked": 0,
                    "bad_dates": []
                }
                continue

            print("Done. Analyzing...", end=" ", flush=True)
            is_good, max_val, days_checked, bad_dates = analyze_json_file(filename)

            results[cbsa_name][year] = {
                "is_good": is_good,
                "max_value": max_val,
                "days_checked": days_checked,
                "bad_dates": bad_dates
            }

            status = "✓ GOOD" if is_good else f"✗ (max: {max_val:.2f} ppm)"
            print(f"{status} (days: {days_checked})")

    # Find years where ALL THREE areas are good
    print("\n" + "=" * 80)
    print("Years where ALL THREE areas have CO <= 4.4 ppm EVERY DAY:")
    print("=" * 80)

    good_years = []
    for year in range(2000, 2011):
        all_good = all(results[cbsa][year]["is_good"] for cbsa in CBSAS)
        if all_good:
            good_years.append(year)
            print(f"  {year}: ✓ ALL GOOD")
        else:
            not_good = [cbsa for cbsa in CBSAS if not results[cbsa][year]["is_good"]]
            print(f"  {year}: ✗ NOT GOOD ({', '.join(not_good)})")

    print("\n" + "=" * 80)
    if good_years:
        answer = ', '.join(map(str, good_years))
        print(f"ANSWER: {answer}")
        with open('answer.txt', 'w') as f:
            f.write(answer)
    else:
        print("ANSWER: None")
        with open('answer.txt', 'w') as f:
            f.write("None")
    print("=" * 80)

if __name__ == "__main__":
    main()

